// A status board: services in a grid, a dot and a sparkline each.
const services = [
  { name: 'Home Assistant', state: 'up', latency: [12, 14, 11, 13, 12, 15, 12, 11, 12, 13], note: '99.98% this month' },
  { name: 'Photo backup', state: 'up', latency: [40, 42, 38, 41, 45, 43, 40, 39, 41, 40], note: '2,418 photos today' },
  { name: 'Media server', state: 'slow', latency: [30, 32, 35, 50, 80, 120, 95, 70, 60, 55], note: 'Transcoding a 4K film' },
  { name: 'Router', state: 'up', latency: [2, 2, 3, 2, 2, 2, 3, 2, 2, 2], note: '412 Mbit/s down' },
  { name: 'Weather station', state: 'down', latency: [5, 5, 6, 5, 0, 0, 0, 0, 0, 0], note: 'No data since 13:52' },
  { name: 'Frames', state: 'up', latency: [20, 22, 21, 19, 23, 20, 21, 22, 20, 21], note: '6 online, 1 asleep' },
]
const tone = { up: 'bg-emerald-400', slow: 'bg-amber-400', down: 'bg-rose-500' }
const stroke = { up: '#34d399', slow: '#fbbf24', down: '#f43f5e' }

const Spark = ({ values, color }) => {
  const max = Math.max(...values, 1)
  const points = values.map((v, i) => `${(i * 100) / (values.length - 1)},${30 - (v / max) * 26}`).join(' ')
  return (
    <svg className="w-full h-8" viewBox="0 0 100 32" preserveAspectRatio="none">
      <polyline points={points} fill="none" stroke={color} strokeWidth={2} strokeLinejoin="round" />
    </svg>
  )
}

export function get(app) {
  const down = services.filter((s) => s.state === 'down').length
  return (
    <div className="flex flex-col gap-4 p-6 bg-zinc-100 text-zinc-900">
      <div className="flex items-center justify-between">
        <span className="text-3xl font-bold">Home lab</span>
        <span className={`rounded-full px-4 py-1 text-sm font-semibold ${down ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
          {down ? `${down} service down` : 'All systems normal'}
        </span>
      </div>
      <div className="flex-1 grid grid-cols-3 gap-4">
        {services.map((s) => (
          <div className="flex flex-col justify-between rounded-xl bg-white p-4 border border-zinc-200">
            <div className="flex items-center gap-2">
              <div className={`w-3 h-3 rounded-full ${tone[s.state]}`} />
              <span className="text-lg font-semibold truncate">{s.name}</span>
            </div>
            <Spark values={s.latency} color={stroke[s.state]} />
            <span className={`text-sm truncate ${s.state === 'down' ? 'text-rose-600 font-medium' : 'text-zinc-500'}`}>{s.note}</span>
          </div>
        ))}
      </div>
    </div>
  )
}
